sys_script.script:
(function executeRule(current, previous) {

    // Skip validation if OTP has already been verified on this record
    if (current.getValue('otp_verified') == 'true') {
        return;
    }

    var enteredCode = current.getValue('otp_code');

    // If no OTP code was provided, block the save
    if (!enteredCode) {
        gs.addErrorMessage('A valid OTP is required before this Service Log can be saved.');
        current.setAbortAction(true);
        return;
    }

    // For updates, validate the entered code against the stored code
    if (current.operation() == 'update') {
        var util = new OTPUtil();
        if (!util.validateOTP(current.getUniqueValue(), enteredCode)) {
            gs.addErrorMessage('A valid OTP is required before this Service Log can be saved.');
            current.setAbortAction(true);
            return;
        }
    }

    // Validation passed — mark the record as verified
    current.setValue('otp_verified', 'true');

})(current, previous);
